LONG = {}
LONG["jesus"] = dict(intro=[
("Who Jesus is", """Jesus of Nazareth is the center of the whole Bible. He is the eternal Son of God, the second person of the Trinity — Father, Son and Holy Spirit — who existed before creation and through whom all things were made. About 2,000 years ago, He became a human being, born as a baby in Bethlehem. He did not stop being God; He added a full human nature. That’s why the Bible calls Him both “Son of God” and “Son of Man.”

He lived about 33 years in Roman-occupied Israel. He spent most of them in Nazareth, a small village in Galilee, working as a craftsman like His legal father Joseph. Around age 30 He began a public ministry of teaching, healing and calling disciples that lasted about three years, ending with His death by crucifixion in Jerusalem under the Roman governor Pontius Pilate, His resurrection three days later, and His ascension into heaven.

Besides the four Gospels, Jesus is mentioned by ancient non-Christian writers, including the Jewish historian Josephus and the Roman historian Tacitus, who records that “Christus” was executed by Pontius Pilate during the reign of Tiberius."""),
("What the Old Testament promised", """For centuries before Jesus was born, the prophets described someone God would send. He would be a descendant of Abraham through whom all nations would be blessed, a son of King David whose kingdom would last forever, a prophet like Moses, born in Bethlehem, coming to Jerusalem riding on a donkey, suffering and being “pierced for our transgressions,” and not being abandoned to the grave. Jesus told His disciples after His resurrection that everything written about Him in the Law of Moses, the Prophets and the Psalms had to be fulfilled.""", ("Isaiah",53)),
], outro=[
("Why Jesus came", """Jesus said, “The Son of Man came to seek and to save the lost,” and “to give His life as a ransom for many.” The Bible teaches that every person has sinned and is separated from God, and that Jesus, who never sinned, died in our place and rose again so that anyone who trusts in Him is forgiven and receives eternal life. “For God so loved the world that He gave His one and only Son, that whoever believes in Him shall not perish but have eternal life.”""", ("John",3)),
("Why Jesus matters today", """Jesus is not only a figure from history. He is risen and alive, and He promised to return. He invites everyone, as He invited Peter and Matthew: “Follow Me.” He also said, “Come to Me, all you who are weary and burdened, and I will give you rest.”""", ("Matthew",11)),
])
LONG["mary"] = dict(intro=[("Who Mary was", """Mary (Miriam in Hebrew) was a young Jewish woman from Nazareth, a small farming village in Galilee. She was probably in her early-to-mid teens when the Bible story begins, the normal age for engagement then. She was engaged to Joseph, a craftsman descended from King David, and she was related to Elizabeth, the wife of a priest named Zechariah.

Nothing in her background made her famous. Nazareth was so insignificant it isn’t mentioned once in the Old Testament. God chose an ordinary young woman in an ordinary village to be the mother of His Son."""),
("Why God chose Mary", """The Bible doesn’t say exactly why God chose Mary, but the angel Gabriel called her “highly favored” and said “the Lord is with you.” Her response shows her character: she asked an honest question (“How will this be?”), then fully trusted God even though saying yes could cost her her engagement, her reputation and possibly her life. Her song of praise, the Magnificat, shows she knew the Scriptures deeply.""", ("Luke",1))],
 outro=[("Why Mary matters today", """Mary is the only person present at both Jesus’ birth and His death, and she was with the church at its beginning. Her life models faith and obedience: “I am the Lord’s servant. May it be to me according to your word.” And her last recorded words in the Gospels are still the best advice: “Do whatever He tells you.”""", ("John",2))])
LONG["joseph-nazareth"] = dict(intro=[("Who Joseph was", """Joseph was a craftsman (tekton) in Nazareth — someone who worked with wood or stone, building furniture, tools or houses. He was a descendant of King David and engaged to Mary. Matthew calls him “a righteous man.” He became the legal father of Jesus, who was conceived by the Holy Spirit, and raised Him as his own son, giving Him His name, His trade, and His legal place in David’s royal line.

The Bible doesn’t say exactly why God chose Joseph, but it shows a man of quiet integrity who protected others and obeyed God immediately, every single time.""")],
 outro=[("Why Joseph matters today", """Joseph never speaks a single word in the Bible, yet he protected the Son of God and His mother through scandal, exile and danger. He shows that faithful, quiet obedience can shape history.""")])
LONG["john-baptist"] = dict(intro=[("Who John was", """John was born about six months before Jesus to an elderly priest, Zechariah, and his wife Elizabeth, a relative of Mary. His birth was announced by the angel Gabriel, who said he would be filled with the Holy Spirit even before he was born and would go before the Lord “in the spirit and power of Elijah.” When pregnant Mary visited Elizabeth, the baby John leaped in Elizabeth’s womb.

As an adult, John lived in the Judean wilderness and became the most famous prophet in Israel in centuries. Even the Jewish historian Josephus wrote about him. His job, foretold by Isaiah and Malachi, was to prepare people for the Messiah.""", ("Luke",1)),
("How John knew Jesus", """John and Jesus were relatives, though John said he did not fully recognize who Jesus was until God showed him a sign: the Spirit descending like a dove at Jesus’ baptism. From then on, John pointed his own followers to Jesus: “Look, the Lamb of God, who takes away the sin of the world!” Several of Jesus’ first disciples, including Andrew, came from John’s circle.""", ("John",1))],
 outro=[("Why John matters today", """Jesus said that among those born of women there was no one greater than John. His greatness came from his humility: “He must become greater; I must become less.” His life was entirely about pointing people to Jesus.""")])
LONG["mary-magdalene"] = dict(intro=[("Who Mary Magdalene was", """Mary Magdalene came from Magdala, a prosperous fishing town on the western shore of the Sea of Galilee, known for salting and exporting fish. “Magdalene” simply means “from Magdala.”

Jesus freed her from seven demons, and from then on she became one of His most devoted followers, traveling with Him and the twelve and helping to fund His ministry with her own money. She is often confused with the unnamed sinful woman who anointed Jesus’ feet, or with Mary of Bethany, but the Bible never connects them. The idea that she had been a prostitute comes from a sermon by Pope Gregory in AD 591, not from Scripture.""", ("Luke",8))],
 outro=[("Why Mary Magdalene matters today", """In an age when women’s testimony wasn’t accepted in court, Jesus chose a woman to be the first witness of His resurrection and sent her to tell the apostles. She was there when others ran — at the cross, at the tomb, and in the garden where she heard Him say her name.""")])
LONG["martha-mary"] = dict(intro=[("Who they were", """Martha and Mary were sisters who lived with their brother Lazarus in Bethany, a village on the eastern slope of the Mount of Olives, about two miles from Jerusalem. Their home was where Jesus stayed during visits to Jerusalem, especially in His last week. John’s Gospel says plainly: “Jesus loved Martha and her sister and Lazarus.”

Martha seems to have been the older sister and the host — practical, busy and outspoken. Mary was more reflective, the one who sat at Jesus’ feet. Both loved Him deeply and both made strong statements of faith.""")],
 outro=[("Why they matter today", """Martha and Mary show that Jesus has real friendships with real people. He gently corrected Martha’s anxiety, defended Mary’s devotion, wept with them in grief, and gave them one of His greatest promises: “I am the resurrection and the life.”""")])
LONG["lazarus"] = dict(intro=[("Who Lazarus was", """Lazarus lived in Bethany with his sisters Martha and Mary. He was a close friend of Jesus — when he got sick, the message his sisters sent simply said, “Lord, the one You love is sick.” His name is a form of Eleazar, meaning “God has helped.” He is a different person from the poor man named Lazarus in Jesus’ parable of the rich man.""")],
 outro=[("Why Lazarus matters today", """Raising Lazarus was the last and greatest of the miracles John records before the cross, and it directly led to the plot to kill Jesus. It was a preview of Jesus’ own resurrection a week later — and of His promise: “Whoever believes in Me will live, even though they die.”""")])
LONG["nicodemus"] = dict(intro=[("Who Nicodemus was", """Nicodemus was a Pharisee — a member of a strict, respected Jewish group devoted to keeping God’s law — and a member of the Sanhedrin, the 71-member ruling council in Jerusalem. Jesus called him “Israel’s teacher,” so he was a well-known scholar. He was likely wealthy, judging by the expensive burial spices he later brought.

How Nicodemus knew Jesus: he had seen or heard about Jesus’ miracles and came to Him at night to ask questions, saying, “We know You are a teacher who has come from God.”""")],
 outro=[("Why Nicodemus matters today", """Nicodemus’s faith grew slowly — from secret questions, to quietly defending Jesus in the council, to publicly burying Him when the disciples were hiding. Jesus gave him, and the world, John 3:16.""")])
LONG["zacchaeus"] = dict(intro=[("Who Zacchaeus was", """Zacchaeus was the chief tax collector in Jericho, a wealthy city on a major trade route. As a “chief” tax collector he oversaw others and profited from all their collections. He was rich, short, and hated by his neighbors as a cheater and collaborator with Rome.

How Zacchaeus knew Jesus: he had obviously heard about Jesus — perhaps that He was a friend of tax collectors — and was so curious that he climbed a tree just to see Him pass by.""")],
 outro=[("Why Zacchaeus matters today", """Jesus noticed the one person everyone else despised, called him by name, and invited Himself to his house. Zacchaeus’s generous change of heart came after Jesus accepted him, not before. Jesus summed it up: “The Son of Man came to seek and to save the lost.”""")])
LONG["paul"] = dict(intro=[
("Who Paul was", """Paul was born in Tarsus, a major city in what is now southern Turkey, around AD 5. He was Jewish, from the tribe of Benjamin, and his parents named him Saul after Israel’s first king. He was also born a Roman citizen, a valuable status that later saved his life more than once. Paul was his Roman name.

As a young man he moved to Jerusalem and studied under Gamaliel, one of the most respected rabbis of the day. He became a Pharisee, and he says he was advancing beyond others his age in zeal for the traditions of his ancestors. He also learned a trade, tentmaking, which he used to support himself throughout his ministry.""", ("Acts",22)),
("How Paul met Jesus", """Paul never met Jesus during His earthly ministry. He was the church’s fiercest enemy: he approved Stephen’s execution and went from house to house dragging Christians to prison. Then on the road to Damascus, the risen Jesus appeared to him in a blinding light and spoke to him by name. Paul later counted this as a true resurrection appearance — the last one — and it made him an apostle.""", ("Acts",9)),
("Why Jesus chose Paul", """Jesus told Ananias, the man sent to heal Paul’s blindness: “This man is My chosen instrument to proclaim My name to the Gentiles and their kings and to the people of Israel. I will show him how much he must suffer for My name.” Paul himself said he was “the worst of sinners,” and that God showed him mercy so that he could be an example of Christ’s patience to everyone who would believe."""),
], outro=[
("What made Paul extraordinary", """Paul traveled roughly 10,000 miles on foot and by ship, planted churches across modern-day Turkey and Greece, wrote 13 of the 27 books of the New Testament, and preached to synagogues, philosophers, governors and kings. More than anyone, he carried the message of Jesus from a Jewish movement in Judea to the wider Roman world."""),
("Why Paul matters today", """Paul’s life is the clearest example of God’s grace: the man who hunted Christians became the greatest missionary. His letters still shape how Christians understand salvation, love and the church. Near the end he wrote, “I have fought the good fight, I have finished the race, I have kept the faith.”""", ("2 Timothy",4)),
])
LONG["stephen"] = dict(intro=[("Who Stephen was", """Stephen was one of the early believers in Jerusalem, likely a Greek-speaking Jew. When the apostles needed help distributing food fairly to widows, the church chose seven men “full of the Spirit and wisdom,” and Stephen was the first named. He did far more than serve tables: he performed great wonders and signs and debated so powerfully that his opponents couldn’t answer him.

The Bible doesn’t say whether Stephen ever met Jesus in person. What it shows is that he knew the Scriptures deeply and was filled with the Holy Spirit.""")],
 outro=[("Why Stephen matters today", """Stephen was the first person to die for following Jesus. He died the way Jesus did — praying for his killers. His death scattered the church and spread the message far beyond Jerusalem, and the young man watching, Saul, would become the apostle Paul.""")])
LONG["barnabas"] = dict(intro=[("Who Barnabas was", """Barnabas was a Levite — from Israel’s priestly tribe — from the island of Cyprus. His given name was Joseph, but the apostles nicknamed him Barnabas, “son of encouragement,” and the name stuck. He was a cousin of John Mark. He was generous, trusted, and willing to take risks on people others had written off.""")],
 outro=[("Why Barnabas matters today", """Without Barnabas, the church might never have trusted Paul, and Mark might never have written his Gospel. Encouragers change history.""")])
LONG["timothy"] = dict(intro=[("Who Timothy was", """Timothy came from Lystra in what is now Turkey. His mother Eunice was a Jewish believer and his father was Greek. He learned the Scriptures from his mother and grandmother Lois, and likely came to faith during Paul’s first visit to Lystra. By Paul’s second visit, the believers spoke highly of him, and Paul invited him to join his team.""")],
 outro=[("Why Timothy matters today", """Timothy shows the power of faith passed down at home and of mentoring. He was young and seems to have been timid, yet Paul trusted him with leading churches.""")])
LONG["lydia"] = dict(intro=[("Who Lydia was", """Lydia came from Thyatira, a city in Asia Minor famous for its purple dye industry, and was living in Philippi in Macedonia selling expensive purple cloth. She was a “worshiper of God” — a Gentile who believed in the God of Israel. She was the head of her own household, suggesting she was a widow or single businesswoman of means.""")],
 outro=[("Why Lydia matters today", """Lydia was the first recorded convert in Europe, and her home became the first church in Philippi — the church Paul later wrote his warmest letter to.""")])
LONG["priscilla-aquila"] = dict(intro=[("Who they were", """Aquila was a Jew from Pontus, near the Black Sea; Priscilla (also called Prisca) was his wife. They had lived in Rome until Emperor Claudius expelled the Jews around AD 49, then moved to Corinth, where they ran a tentmaking business. Paul, a tentmaker too, stayed and worked with them. They later moved to Ephesus and back to Rome, hosting churches in their home wherever they went.""")],
 outro=[("Why they matter today", """Priscilla and Aquila show a married couple serving God together through their work, their home and their hospitality — and teaching others with grace.""")])
